const input = $json.body || $json;
const event = input.eventType;
const customerName = input.customerName || 'Valued Customer';
const email = input.customerEmail || (input.testMode === true ? 'yashchauh8057@gmail.com' : '');
const orderId = input.orderId || '';
const products = Array.isArray(input.items) ? input.items : [];
const productText = products.map(p => `${p.name || 'Product'} x${p.quantity || 1}`).join(', ') || 'your recent purchase';
const money = `${input.currency || 'INR'} ${Number(input.totalAmount || 0).toFixed(2)}`;
if (!email) throw new Error('customerEmail is required');
const messages = {
  welcome: { subject: 'Welcome to Our Store', body: `Welcome to our store, ${customerName}! We are happy to have you with us. Browse our latest products and enjoy a simple shopping experience.` },
  order_confirmation: { subject: `Your Order ${orderId} Has Been Confirmed`, body: `Your payment was successful. Order ${orderId} contains: ${productText}. Total paid: ${money}. Expected delivery: ${input.expectedDeliveryDate || 'as shown in your order details'}.` },
  thank_you_store_visit: { subject: 'Thank You for Shopping With Us', body: `Thank you for visiting us, ${customerName}. Your payment for order ${orderId} was completed successfully. Purchased products: ${productText}.` },
  abandoned_cart: { subject: 'You Left Something in Your Cart', body: `You still have these products in your cart: ${productText}. Use the link below to continue shopping.` },
  order_shipped: { subject: `Your Order ${orderId} Has Been Shipped`, body: `Your order has been shipped. Courier: ${input.courierName || 'our delivery partner'}. Expected delivery: ${input.expectedDeliveryDate || 'please check the tracking link'}. Tracking link: ${input.trackingUrl || 'available in your account'}.` },
  order_delivered: { subject: `Your Order ${orderId} Has Been Delivered`, body: `Your order was delivered successfully. We hope you enjoy your purchase. Please contact us if you need return or product support.` },
  review_request: { subject: 'How Was Your Purchase?', body: `We would love to hear your feedback about ${productText}. Please rate your purchase and share your review using the link below.` },
  related_recommendation: { subject: 'Products You May Also Like', body: `Based on your recent purchase, we think you may like these products: ${input.recommendedProducts || 'new products from our store'}.` },
  back_in_stock: { subject: 'Your Requested Product Is Back in Stock', body: `${input.productName || 'The product you requested'} is now available. Current price: ${money}. You can purchase it using the link below.` },
  price_drop: { subject: 'Good News: The Price Has Dropped', body: `The price of ${input.productName || 'your watched product'} has changed from ${input.oldPrice || 'the previous price'} to ${input.newPrice || money}. View the product using the link below.` },
  return_confirmation: { subject: `Return Request ${input.returnRequestId || ''} Received`, body: `We received your return request for order ${orderId}. Please follow the return instructions provided in your account.` },
  refund_confirmation: { subject: `Your Refund for Order ${orderId} Has Been Processed`, body: `Your refund of ${input.refundAmount || money} has been processed. Transaction reference: ${input.refundTransactionId || 'available in your account'}.` },
  loyalty_points: { subject: 'You Earned New Reward Points', body: `You earned ${input.pointsEarned || 0} points. Your current balance is ${input.pointsBalance || 0} points. View your rewards in your account.` }
};
const selected = messages[event];
if (!selected) throw new Error(`Unsupported eventType: ${event}`);
const actionUrl = input.actionUrl || input.checkoutUrl || input.trackingUrl || input.reviewUrl || input.productUrl || '';
const button = actionUrl ? `<p><a href="${actionUrl}" style="background:#2563eb;color:white;padding:12px 18px;text-decoration:none;border-radius:6px">View Details</a></p>` : '';
const attachmentUrl = input.invoiceUrl || input.billUrl || input.refundReceiptUrl || '';
const html = `<div style="font-family:Arial,sans-serif;max-width:650px;margin:auto;color:#222"><h2 style="color:#2563eb">${selected.subject}</h2><p>Hello ${customerName},</p><p>${selected.body}</p>${button}<p>Regards,<br><strong>Your Store Team</strong></p></div>`;
return [{ json: { ...input, customerEmail: email, emailSubject: selected.subject, emailHtml: html, attachmentUrl } }];
